#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    #[test]
    fn request_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000001\",\n  \"type\": \"https://trusttasks.org/spec/rooms/keys/seal/0.1#request\",\n  \"issuer\": \"did:example:agent\",\n  \"recipient\": \"did:example:oracle\",\n  \"issuedAt\": \"2026-01-01T00:00:00Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"roomId\": \"did:webvh:example.com:rooms:northwind\",\n    \"key\": \"giXFLTGBdnnQJRoIsktuIg\",\n    \"version\": 1,\n    \"plaintext\": \"IyBOb3J0aHdpbmQKCkRvIG5vdCByZXByaWNlIGJlZm9yZSByZW5ld2FsLg\"\n  }\n}\n";
        let doc: crate::TrustTask<super::Payload> =
            serde_json::from_str(JSON).expect("deserialize request example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "request example failed round-trip");
    }
    #[test]
    fn response_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000002\",\n  \"type\": \"https://trusttasks.org/spec/rooms/keys/seal/0.1#response\",\n  \"issuer\": \"did:example:oracle\",\n  \"recipient\": \"did:example:agent\",\n  \"issuedAt\": \"2026-01-01T00:00:01Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"sealed\": {\n      \"ciphertext\": \"3QhV1sVvR0m5xAqZ7Aw2mQnR4vBk8QLp3wXc9TgYw\",\n      \"nonce\": \"b0Zt8Qm2Yq1sVvR0\",\n      \"epoch\": 4\n    }\n  }\n}\n";
        let doc: crate::TrustTask<super::Response> =
            serde_json::from_str(JSON).expect("deserialize response example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "response example failed round-trip");
    }
    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "No version. The version is bound into the ciphertext, so a request without one is asking for a record that cannot be bound to where it will live — and there is no defaulting that would be honest, because only the caller knows which write shape it is about to use.",
                "{\n  \"key\": \"giXFLTGBdnnQJRoIsktuIg\",\n  \"plaintext\": \"IyBOb3J0aHdpbmQ\",\n  \"roomId\": \"did:webvh:example.com:rooms:northwind\"\n}",
            ),
            (
                "A negative version. Versions are assigned from a monotonic counter that starts at 1, and `0` is the create-only precondition — nothing below that names a record that can exist.",
                "{\n  \"key\": \"giXFLTGBdnnQJRoIsktuIg\",\n  \"plaintext\": \"IyBOb3J0aHdpbmQ\",\n  \"roomId\": \"did:webvh:example.com:rooms:northwind\",\n  \"version\": -1\n}",
            ),
            (
                "No plaintext. Sealing nothing is not a coherent request; the member is the whole input.",
                "{\n  \"key\": \"giXFLTGBdnnQJRoIsktuIg\",\n  \"roomId\": \"did:webvh:example.com:rooms:northwind\",\n  \"version\": 1\n}",
            ),
            (
                "The record's parts sent separately. Splitting title/body/tags would let a host read the shape of the material from ciphertext lengths — the sealed tiers seal one blob for exactly this reason, so the structure belongs inside `plaintext`, not beside it.",
                "{\n  \"key\": \"giXFLTGBdnnQJRoIsktuIg\",\n  \"plaintext\": \"IyBOb3J0aHdpbmQ\",\n  \"roomId\": \"did:webvh:example.com:rooms:northwind\",\n  \"title\": \"Northwind\",\n  \"version\": 1\n}",
            ),
            (
                "Bare/unnamespaced ext key — SPEC §4.5.1 requires every immediate child of ext to be reverse-DNS namespaced.",
                "{\n  \"ext\": {\n    \"bare-key\": {\n      \"anything\": \"here\"\n    }\n  },\n  \"key\": \"giXFLTGBdnnQJRoIsktuIg\",\n  \"plaintext\": \"IyBOb3J0aHdpbmQ\",\n  \"roomId\": \"did:webvh:example.com:rooms:northwind\",\n  \"version\": 1\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
}
